mapper.select:
SELECT , t.name AS trainer_name

LEFT JOIN trainers t ON t.id = r.trainer_id
WHERE r.starts_at >= #{weekStart} AND r.starts_at < #{weekEnd}
AND r.trainer_id = #{trainerId}
AND r.reservation_type = #{reservationType}
AND r.status = #{status}
ORDER BY r.starts_at, r.id

SELECT EXISTS (
    SELECT 1 FROM reservations r
    WHERE r.trainer_id = #{trainerId}
      AND r.status NOT IN ('CANCELLED', 'NO_SHOW')
      AND r.starts_at < #{endsAt} AND r.ends_at > #{startsAt}
    AND r.id != #{excludeReservationId}
)

mapper.insert:
INSERT INTO reservations (
    member_id, trainer_id, customer_name, customer_phone, reservation_type,
    status, starts_at, ends_at, memo, created_by
) VALUES (
    #{memberId}, #{trainerId}, #{customerName}, #{customerPhone}, #{reservationType},
    #{status}, #{startsAt}, #{endsAt}, #{memo}, #{createdBy}
)

mapper.update:
UPDATE reservations
SET status = #{nextStatus},
    cancellation_reason = #{cancellationReason},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{reservationId}
    AND status = #{currentStatus}
